-- v33c: dvi kalbos - turinio vertimai (LT lieka pagrindiniuose stulpeliuose, kitos kalbos - i18n jsonb).
-- products.i18n = { "en": { name, tagline, description, subtitle, mood_title, mood_line, badge, ingredients } }
-- scents.i18n = { "en": { mood_title, mood_line } } · families.i18n = { "en": { name, hint } }
-- categories.i18n = { "en": { name, description } } · note_media.i18n = { "en": { name } }
-- settings.data.i18n.en - parduotuvės tekstai pagal stabilius raktus (rails / shipping / topbar / slides - pagal id, tiles - pagal key)
-- RLS: stulpelio pridėjimas politikų nekeičia (tos pačios eilutės, tos pačios teisės).

alter table public.products add column if not exists i18n jsonb not null default '{}'::jsonb;
alter table public.scents add column if not exists i18n jsonb not null default '{}'::jsonb;
alter table public.families add column if not exists i18n jsonb not null default '{}'::jsonb;
alter table public.categories add column if not exists i18n jsonb not null default '{}'::jsonb;
alter table public.note_media add column if not exists i18n jsonb not null default '{}'::jsonb;

-- Prekės (58): pavadinimas (pagal tipą: Scented candle / Fragrance oil / Reed diffuser…), šūkis, aprašymas
update public.products p set i18n = p.i18n || v.t
from (values
  ('aliejus-sired', '{"en":{"name":"Fragrance oil SIDORE","tagline":"Pear, blackcurrant and rose","description":"Fragrance oil SIDORE - a juicy fruity-floral fragrance for electric diffusers and humidifiers. Top notes of pear, blackcurrant and pink pepper; a heart of rose, jasmine and heliotrope; a base of vanilla, cedar and patchouli. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Fills your home with warmth and passionate elegance."}}'::jsonb),
  ('aliejus-waydore', '{"en":{"name":"Fragrance oil WAYDORE","tagline":"Bergamot, tuberose and vanilla","description":"Fragrance oil WAYDORE - a soft white-floral fragrance for electric diffusers and humidifiers. Top notes of bergamot and orange blossom; a heart of tuberose and jasmine; a base of vanilla, white musk and cedar. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Creates a bright, calm mood at home."}}'::jsonb),
  ('aromatinis-aliejus-amodore', '{"en":{"name":"Fragrance oil AMODORE","tagline":"Blackcurrant, apricot and vanilla","description":"Fragrance oil AMODORE - a juicy fruity-floral fragrance for electric diffusers and humidifiers. Top notes of blackcurrant, grapefruit and orange; a heart of rose, jasmine and apricot; a base of vanilla, tonka bean and musk. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Brings a joyful, warm mood to your home."}}'::jsonb),
  ('aromatinis-aliejus-chadore', '{"en":{"name":"Fragrance oil CHADORE","tagline":"Bergamot, vetiver and tonka bean","description":"Fragrance oil CHADORE - an elegant, warm woody fragrance for electric diffusers and humidifiers. Top notes of bergamot, mandarin, peach and ginger; a heart of cedar, vetiver and pepper; a base of tonka bean, vanilla and labdanum. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Brings calm and elegance to your home."}}'::jsonb),
  ('aromatinis-aliejus-cledore', '{"en":{"name":"Fragrance oil CLEDORE","tagline":"Peony, lychee and powdery rose","description":"Fragrance oil CLEDORE - a soft, powdery rose fragrance for electric diffusers and humidifiers. Top notes of peony, lychee and freesia; a heart of rose, lily of the valley and magnolia; a base of amber and cedar. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Creates a calm, clean and feminine atmosphere."}}'::jsonb),
  ('aromatinis-aliejus-creedore', '{"en":{"name":"Fragrance oil CREEDORE","tagline":"Pineapple, birch and oakmoss","description":"Fragrance oil CREEDORE - a light, fresh fragrance for electric diffusers and humidifiers. Top notes of bergamot, blackcurrant and apple; a heart of pineapple, patchouli and jasmine; a base of birch, oakmoss and musk. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Refreshes the room and leaves a feeling of cleanliness."}}'::jsonb),
  ('aromatinis-aliejus-crydore', '{"en":{"name":"Fragrance oil CRYDORE","tagline":"Pomegranate, peony and magnolia","description":"Fragrance oil CRYDORE - a fresh, luminous floral fragrance for electric diffusers and humidifiers. Top notes of pomegranate and yuzu; a heart of peony, magnolia and lotus; a base of amber, musk and mahogany. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Fills your home with freshness and light."}}'::jsonb),
  ('aromatinis-aliejus-deladore', '{"en":{"name":"Fragrance oil DELADORE","tagline":"Green apple, cucumber and magnolia","description":"Fragrance oil DELADORE - a fresh, juicy fragrance for electric diffusers and humidifiers. Top notes of cucumber, grapefruit and magnolia; a heart of green apple, tuberose and lily of the valley; a base of sandalwood and white amber. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Refreshes the room and brings a sense of lightness."}}'::jsonb),
  ('aromatinis-aliejus-eufodore', '{"en":{"name":"Fragrance oil EUFODORE","tagline":"Pomegranate, black orchid and mahogany","description":"Fragrance oil EUFODORE - an exotic, enveloping fragrance for electric diffusers and humidifiers. Top notes of pomegranate and persimmon; a heart of black orchid, lotus and champaca; a base of mahogany, amber and black violet. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Creates a mysterious, warm mood in the evening."}}'::jsonb),
  ('aromatinis-aliejus-goodore', '{"en":{"name":"Fragrance oil GOODORE","tagline":"Almond, tuberose and cocoa","description":"Fragrance oil GOODORE - a seductive, warm floral and cocoa fragrance for electric diffusers and humidifiers. Top notes of almond, coffee and bergamot; a heart of tuberose, jasmine and orange blossom; a base of tonka bean, cocoa and vanilla. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Fills your home with warmth and mystery."}}'::jsonb),
  ('aromatinis-aliejus-invidore', '{"en":{"name":"Fragrance oil INVIDORE","tagline":"Marine notes, bay leaf and patchouli","description":"Fragrance oil INVIDORE - a warm woody fragrance for electric diffusers and humidifiers. Top notes of grapefruit, marine notes and mandarin; a heart of bay leaf and jasmine; a base of guaiac wood, ambergris and patchouli. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Brings warmth and calm to your home. Perfect for bath rituals or as a gift."}}'::jsonb),
  ('aromatinis-aliejus-jadore', '{"en":{"name":"Fragrance oil JADORE","tagline":"Pear, ylang-ylang and jasmine","description":"Fragrance oil JADORE - a luxurious fruity-floral fragrance for electric diffusers and humidifiers. Top notes of pear, peach and mandarin; a heart of ylang-ylang, jasmine and rose; a base of vanilla, musk and cedar. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Fills your home with light and gentle elegance."}}'::jsonb),
  ('aromatinis-aliejus-madore', '{"en":{"name":"Fragrance oil MADORE","tagline":"Orange, rose and patchouli","description":"Fragrance oil MADORE - an elegant, fresh amber fragrance for electric diffusers and humidifiers. Top notes of orange and bergamot; a heart of rose and jasmine; a base of patchouli and vetiver. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Fills your home with elegance and freshness."}}'::jsonb),
  ('aromatinis-aliejus-nifodore', '{"en":{"name":"Fragrance oil NIFODORE","tagline":"Aldehydes, rose and jasmine","description":"Fragrance oil NIFODORE - a classic, powdery floral fragrance for electric diffusers and humidifiers. Top notes of aldehydes, neroli and bergamot; a heart of rose, jasmine and ylang-ylang; a base of sandalwood and vanilla. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Creates an elegant, timeless mood."}}'::jsonb),
  ('aromatinis-aliejus-opiudore', '{"en":{"name":"Fragrance oil OPIUDORE","tagline":"Coffee, jasmine and vanilla","description":"Fragrance oil OPIUDORE - a rich, gourmand coffee and vanilla fragrance for electric diffusers and humidifiers. Top notes of pear, pink pepper and orange blossom; a heart of coffee and jasmine; a base of vanilla, patchouli and cedar. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Creates a warm, seductive mood in the evening."}}'::jsonb),
  ('aromatinis-aliejus-sauvadore', '{"en":{"name":"Fragrance oil SAUVADORE","tagline":"Bergamot, lavender and cedar","description":"Fragrance oil SAUVADORE - a fresh, clean fragrance for electric diffusers and humidifiers. Top notes of bergamot and pepper; a heart of Sichuan pepper, lavender and vetiver; a base of ambroxan, cedar and labdanum. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Your home smells light and clean, like after the rain."}}'::jsonb),
  ('aromatinis-aliejus-scentdore', '{"en":{"name":"Fragrance oil SCENTDORE","tagline":"Ginger, maninka fruit and leather","description":"Fragrance oil SCENTDORE - a warm, spicy fragrance for electric diffusers and humidifiers. Top notes of ginger, mandarin and bergamot; a heart of maninka fruit and lavender; a base of leather and woody notes. A few drops in your diffuser''s water are enough - the scent spreads evenly through the whole room. For room fragrancing only. Creates a warm, elegant mood in the evening."}}'::jsonb),
  ('difuzorius-codore', '{"en":{"name":"Reed diffuser CODORE","tagline":"Ginger, mint and amber","description":"Reed diffuser CODORE - a fresh, clean fragrance for your home. Top notes of ginger, lemon and mandarin; a heart of mint; a base of amber and vetiver. The reeds draw up the fragrance evenly and diffuse it with no flame or electricity. Perfect for the living room, hallway or bathroom. Turn the reeds every few days to refresh the scent. Your home smells light and clean, like after the rain."}}'::jsonb),
  ('difuzorius-creedore', '{"en":{"name":"Reed diffuser CREEDORE","tagline":"Lemon, oakmoss and musk","description":"Reed diffuser CREEDORE - a light, fresh fragrance for your home. Top notes of bergamot, blackcurrant, apple, lemon and pink pepper; a heart of pineapple, patchouli and jasmine; a base of birch, musk, oakmoss, cedar and ambroxan. The reeds draw up the fragrance evenly and diffuse it with no flame or electricity. Ideal for the living room, bedroom or office. Turn the reeds every few days to refresh the scent. Refreshes the room and leaves a feeling of cleanliness."}}'::jsonb),
  ('difuzorius-invidore', '{"en":{"name":"Reed diffuser INVIDORE","tagline":"Marine notes, bay laurel and patchouli","description":"Reed diffuser INVIDORE - a warm woody fragrance for your home. Top notes of grapefruit, marine notes and mandarin; a heart of bay leaf and jasmine; a base of ambergris, guaiac wood, oakmoss and patchouli. The reeds draw up the fragrance evenly and diffuse it with no flame or electricity. Perfect for the living room, hallway or bathroom. Turn the reeds every few days to refresh the scent. Brings warmth and calm to your home."}}'::jsonb),
  ('difuzorius-libradore', '{"en":{"name":"Reed diffuser LIBRADORE","tagline":"Lavender, orange blossom and vanilla","description":"Reed diffuser LIBRADORE - a warm, enveloping amber fragrance for your home. Top notes of mandarin, petitgrain, lavandin and blackcurrant; a heart of lavender, jasmine and orange blossom; a base of vanilla, cedar, ambergris and musk. The reeds draw up the fragrance evenly and diffuse it with no flame or electricity. Perfect for the living room, hallway or bathroom. Turn the reeds every few days to refresh the scent. Your home fills with warmth and cosiness."}}'::jsonb),
  ('difuzorius-millidore', '{"en":{"name":"Reed diffuser MILLIDORE","tagline":"Juicy mandarin, spicy cinnamon and refined leather","description":"Reed diffuser MILLIDORE - an elegant floral fragrance for your home. Top notes of red mandarin, grapefruit and mint; a heart of rose, cinnamon and spices; a base of leather, amber, woody notes and patchouli. The reeds draw up the fragrance evenly and diffuse it with no flame or electricity. Ideal for the living room, bedroom or office. Turn the reeds every few days to refresh the scent. Creates a bright, romantic mood."}}'::jsonb),
  ('difuzorius-sauvadore', '{"en":{"name":"Reed diffuser SAUVADORE","tagline":"Fresh bergamot, lavender and cedar","description":"Reed diffuser SAUVADORE - a fresh, clean fragrance for your home. Top notes of bergamot and pepper; a heart of Sichuan pepper, lavender, pink pepper, vetiver, patchouli, geranium and elemi; a base of ambroxan, cedar and labdanum. The reeds draw up the fragrance evenly and diffuse it with no flame or electricity. Perfect for the living room, hallway or bathroom. Turn the reeds every few days to refresh the scent. Your home smells light and clean, like after the rain."}}'::jsonb),
  ('difuzorius-sired', '{"en":{"name":"Reed diffuser SIDORE","tagline":"Juicy blackcurrant and rose petals","description":"Reed diffuser SIDORE - an elegant floral fragrance for your home. Top notes of pear, blackcurrant, pink pepper and grapefruit; a heart of rose, jasmine, heliotrope and pineapple; a base of vanilla, cedar, patchouli and amberwood. The reeds draw up the fragrance evenly and diffuse it with no flame or electricity. Ideal for the living room, bedroom or office. Turn the reeds every few days to refresh the scent. Creates a bright, romantic mood."}}'::jsonb),
  ('difuzorius-tobadore', '{"en":{"name":"Reed diffuser TOBADORE","tagline":"Tobacco leaf, tonka bean and dried fruits","description":"Reed diffuser TOBADORE - a warm, enveloping amber fragrance for your home. Top notes of tobacco leaf and spices; a heart of tonka bean, tobacco flower, vanilla and cocoa; a base of dried fruits and woody notes. The reeds draw up the fragrance evenly and diffuse it with no flame or electricity. Perfect for the living room, hallway or bathroom. Turn the reeds every few days to refresh the scent. Your home fills with warmth and cosiness."}}'::jsonb),
  ('difuzorius-vanidore', '{"en":{"name":"Reed diffuser VANIDORE","tagline":"Spicy cardamom, creamy vanilla and warm sandalwood","description":"Reed diffuser VANIDORE - a warm, enveloping amber fragrance for your home. Top notes of cardamom, mandarin and saffron; a heart of vanilla, spices and floral notes; a base of sandalwood, amber and tonka bean. The reeds draw up the fragrance evenly and diffuse it with no flame or electricity. Perfect for the living room, hallway or bathroom. Turn the reeds every few days to refresh the scent. Your home fills with warmth and cosiness."}}'::jsonb),
  ('difuzorius-waydore-2', '{"en":{"name":"Reed diffuser WAYDORE","tagline":"Bergamot, tuberose and creamy vanilla","description":"Reed diffuser WAYDORE - a soft white-floral fragrance for your home. Top notes of bergamot and orange blossom; a heart of tuberose and jasmine; a base of vanilla, white musk and cedar. The reeds draw up the fragrance evenly and diffuse it with no flame or electricity. Ideal for the living room, bedroom or office. Turn the reeds every few days to refresh the scent. Creates a bright, calm mood at home."}}'::jsonb),
  ('elektrinis-difuzorius-humidifier-blow', '{"en":{"name":"Electric diffuser Humidifier Blow","tagline":"Quiet aroma diffuser with lighting","badge":"New","description":"Electric diffuser Humidifier Blow - an electric aroma diffuser that quietly and evenly spreads your favourite fragrance throughout your home. Water tank - 4 L, running time - up to 48 h. Suitable for rooms up to 150 m². Its soft LED light creates a cosy atmosphere. Add a few drops of fragrance oil to the water and your home will fill with scent. Ideal for the bedroom, living room or study."}}'::jsonb),
  ('bacadore', '{"en":{"tagline":"Saffron, amberwood and fir resin","description":"BACADORE - a calm, rich woody fragrance for her and for him. Top notes of saffron and jasmine; a heart of amberwood, ambergris and hedione; a base of fir resin, cedar, sugar, ambroxan and oakmoss. Calm and self-assured - the depth of the woods gives it character. Eau de Parfum concentration - long-lasting on the skin."}}'::jsonb),
  ('codore-2', '{"en":{"tagline":"Ginger, mint and amber","description":"CODORE - a clean, fresh fragrance for men. Top notes of ginger, lemon and mandarin; a heart of mint; a base of amber and vetiver. Light and clean - it brings freshness and energy. Eau de Parfum concentration - long-lasting on the skin. Every fragrance develops differently on each person''s skin, so it''s worth starting with a 2 ml sample."}}'::jsonb),
  ('creedore', '{"en":{"tagline":"Lemon, oakmoss and musk","description":"CREEDORE - a fresh, luminous fragrance for men. Top notes of bergamot, blackcurrant, apple, lemon and pink pepper; a heart of pineapple, patchouli and jasmine; a base of birch, musk, oakmoss, cedar and ambroxan. Fresh as the morning air, it leaves a clean, bright impression. Eau de Parfum concentration - long-lasting on the skin."}}'::jsonb),
  ('invidore', '{"en":{"tagline":"Marine notes, bay laurel and patchouli","description":"INVIDORE - a calm, rich woody fragrance for men. Top notes of grapefruit, marine notes and mandarin; a heart of bay leaf and jasmine; a base of ambergris, guaiac wood, oakmoss and patchouli. Calm and self-assured - the depth of the woods gives it character. Eau de Parfum concentration - long-lasting on the skin. Every fragrance develops differently on each person''s skin, so it''s worth starting with a 2 ml sample."}}'::jsonb),
  ('libradore', '{"en":{"tagline":"Lavender, orange blossom and vanilla","description":"LIBRADORE - a rich amber fragrance for women. Top notes of mandarin, petitgrain, lavandin and blackcurrant; a heart of lavender, jasmine and orange blossom; a base of vanilla, cedar, ambergris and musk. Rich and mysterious - enveloping and unforgettable. Eau de Parfum concentration - long-lasting on the skin. Every fragrance develops differently on each person''s skin, so it''s worth starting with a 2 ml sample."}}'::jsonb),
  ('millidore', '{"en":{"tagline":"Juicy mandarin, spicy cinnamon and refined leather","description":"MILLIDORE - a soft floral fragrance for men. Top notes of red mandarin, grapefruit and mint; a heart of rose, cinnamon and spices; a base of leather, amber, woody notes and patchouli. Subtle and soft, it easily becomes an everyday companion. Eau de Parfum concentration - long-lasting on the skin."}}'::jsonb),
  ('sauvadore', '{"en":{"tagline":"Fresh bergamot, lavender and cedar","description":"SAUVADORE - a clean, fresh fragrance for men. Top notes of bergamot and pepper; a heart of Sichuan pepper, lavender, pink pepper, vetiver, patchouli, geranium and elemi; a base of ambroxan, cedar and labdanum. Light and clean - ideal for warm days, the office and after sport. Eau de Parfum concentration - long-lasting on the skin."}}'::jsonb),
  ('sired', '{"en":{"tagline":"Juicy blackcurrant and rose petals","description":"SIDORE - a soft floral fragrance for women. Top notes of pear, blackcurrant, pink pepper and grapefruit; a heart of rose, jasmine, heliotrope and pineapple; a base of vanilla, cedar, patchouli and amberwood. Subtle and soft, it easily becomes an everyday companion. Eau de Parfum concentration - long-lasting on the skin."}}'::jsonb),
  ('tobadore', '{"en":{"tagline":"Tobacco leaf, tonka bean and dried fruits","description":"TOBADORE - a rich amber fragrance for her and for him. Top notes of tobacco leaf and spices; a heart of tonka bean, tobacco flower, vanilla and cocoa; a base of dried fruits and woody notes. Rich and mysterious - enveloping and unforgettable. Eau de Parfum concentration - long-lasting on the skin. Every fragrance develops differently on each person''s skin, so it''s worth starting with a 2 ml sample."}}'::jsonb),
  ('vanidore', '{"en":{"tagline":"Spicy cardamom, creamy vanilla and warm sandalwood","description":"VANIDORE - a rich amber fragrance for her and for him. Top notes of cardamom, mandarin and saffron; a heart of vanilla, spices and floral notes; a base of sandalwood, amber and tonka bean. Rich and mysterious - enveloping and unforgettable. Eau de Parfum concentration - long-lasting on the skin."}}'::jsonb),
  ('waydore', '{"en":{"tagline":"Bergamot, tuberose and creamy vanilla","description":"WAYDORE - a soft floral fragrance for women. Top notes of bergamot and orange blossom; a heart of tuberose and jasmine; a base of vanilla, white musk and cedar. Subtle and soft, it easily becomes an everyday companion. Eau de Parfum concentration - long-lasting on the skin."}}'::jsonb),
  ('kvapni-zvake-amodore', '{"en":{"name":"Scented candle AMODORE","tagline":"Blackcurrant, apricot and vanilla","description":"Scented candle AMODORE - a juicy fruity-floral fragrance for a cosy home. Top notes of blackcurrant, grapefruit and orange; a heart of rose, jasmine and apricot; a base of vanilla, tonka bean and musk. On the first burn, let it burn for at least an hour so the wax melts evenly across the whole surface. Brings a joyful, warm mood to your home."}}'::jsonb),
  ('kvapni-zvake-angedore', '{"en":{"name":"Scented candle ANGEDORE","tagline":"Candyfloss, honey and patchouli","description":"Scented candle ANGEDORE - a sweet, gourmand fragrance for a cosy home. Top notes of candyfloss, bergamot and blackcurrant; a heart of honey, red berries and plum; a base of patchouli, chocolate, caramel and vanilla. On the first burn, let it burn for at least an hour so the wax melts evenly across the whole surface. Your home fills with sweet, enveloping comfort."}}'::jsonb),
