  ('kvapni-zvake-jadore', '{"en":{"name":"Scented candle JADORE","tagline":"Pear, ylang-ylang and jasmine","description":"Scented candle JADORE - a luxurious fruity-floral fragrance for a cosy home. Top notes of pear, peach and mandarin; a heart of ylang-ylang, jasmine and rose; a base of vanilla, musk and cedar. On the first burn, let it burn for at least an hour so the wax melts evenly across the whole surface. Fills your home with light and gentle elegance."}}'::jsonb),
  ('kvapni-zvake-libradore', '{"en":{"name":"Scented candle LIBRADORE","tagline":"Lavender, orange blossom and vanilla","description":"Scented candle LIBRADORE - a warm, enveloping amber fragrance for a cosy home. Top notes of mandarin, petitgrain and blackcurrant; a heart of lavender, orange blossom and jasmine; a base of vanilla, ambergris and musk. On the first burn, let it burn for at least an hour so the wax melts evenly across the whole surface. Your home fills with warmth and cosiness. Perfect for bath rituals or as a gift."}}'::jsonb),
  ('kvapni-zvake-mavidore', '{"en":{"name":"Scented candle MAVIDORE","tagline":"Cactus flower, rosebud and cedar","description":"Scented candle MAVIDORE - a soft, bright floral fragrance for a cosy home. Top notes of cactus flower; a heart of pink freesia, rosebud and jasmine; a base of cedar and woody notes. On the first burn, let it burn for at least an hour so the wax melts evenly across the whole surface. Creates a light, fresh and feminine mood."}}'::jsonb),
  ('kvapni-zvake-sauvadore', '{"en":{"name":"Scented candle SAUVADORE","tagline":"Bergamot, lavender and cedar","description":"Scented candle SAUVADORE - a fresh, clean fragrance for a cosy home. Top notes of bergamot and pepper; a heart of Sichuan pepper, lavender and vetiver; a base of ambroxan, cedar and labdanum. On the first burn, let it burn for at least an hour so the wax melts evenly across the whole surface. Your home smells light and clean, like after the rain."}}'::jsonb),
  ('kvapni-zvake-scentdore', '{"en":{"name":"Scented candle SCENTDORE","tagline":"Ginger, maninka fruit and leather","description":"Scented candle SCENTDORE - a warm, spicy fragrance for a cosy home. Top notes of ginger, mandarin and bergamot; a heart of maninka fruit and lavender; a base of leather and woody notes. On the first burn, let it burn for at least an hour so the wax melts evenly across the whole surface. Creates a warm, elegant mood in the evening."}}'::jsonb),
  ('kvapni-zvake-sired', '{"en":{"name":"Scented candle SIDORE","tagline":"Pear, blackcurrant and rose","description":"Scented candle SIDORE - a juicy fruity-floral fragrance for a cosy home. Top notes of pear, blackcurrant and pink pepper; a heart of rose, jasmine and heliotrope; a base of vanilla, cedar and patchouli. On the first burn, let it burn for at least an hour so the wax melts evenly across the whole surface. Fills your home with warmth and passionate elegance."}}'::jsonb),
  ('zvake-waydore', '{"en":{"name":"Scented candle WAYDORE","tagline":"Bergamot, tuberose and vanilla","description":"Scented candle WAYDORE - a soft white-floral fragrance for a cosy home. Top notes of bergamot and orange blossom; a heart of tuberose and jasmine; a base of vanilla, white musk and cedar. On the first burn, let it burn for at least an hour so the wax melts evenly across the whole surface. Creates a bright, calm mood at home."}}'::jsonb)
) as v(id, t)
where p.id = v.id;

